export const meta = {
  "slug": "phosphor-sliders-horizontal",
  "family": "phosphor",
  "name": "sliders-horizontal",
  "category": "Interface",
  "motion": "gear",
  "component": "createPhosphorSlidersHorizontalIcon"
};

export function createPhosphorSlidersHorizontalIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
